const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.files}</svg>`;
const nav=[['overview','home','Your overview'],['plan','plan','Action plan'],['documents','files','Documents'],['letters','mail','Letters'],['memories','heart','Memories'],['evidence','eye','Evidence review'],['privacy','shield','Privacy & processing']];
let state={route:location.hash.slice(1)||'overview',completed:['notify-employer','gather-records'],waiting:[],reviewed:[],favorite:[],filter:'all',docFilter:'all',query:'',selectedFinding:'insurance',savedDraft:'',imported:false,largeText:false};
try{const saved=JSON.parse(localStorage.getItem('afterword-design-v2')||'{}');for(const k of ['completed','waiting','reviewed','favorite','savedDraft','largeText'])if(saved[k]!==undefined)state[k]=saved[k]}catch{}
const persist=()=>{try{localStorage.setItem('afterword-design-v2',JSON.stringify({completed:state.completed,waiting:state.waiting,reviewed:state.reviewed,favorite:state.favorite,savedDraft:state.savedDraft,largeText:state.largeText}))}catch{}};
const tasks=[{id:'insurance',title:'Ask about a possible life insurance policy',description:'Two records need a closer look before you take the next step.',icon:'shield',tone:'amber',status:'review',date:'Follow up Sep 24',category:'Insurance',source:'2 source records',doc:'policy',value:'$250,000 mentioned in a 2019 letter'}, {id:'storage',title:'Visit the storage unit before cancelling',description:'There may be personal belongings inside. Arrange a visit first.',icon:'files',tone:'',status:'ready',date:'Your reminder · Sep 26',category:'Personal belongings',source:'1 source record',doc:'storage',value:'$129 monthly charge'}, {id:'subscriptions',title:'Review two recurring subscriptions',description:'A gym membership and a streaming service still appear on the statement.',icon:'refresh',tone:'blue',status:'ready',date:'When you’re ready',category:'Subscriptions',source:'1 source record',doc:'statement',value:'$55.48 in monthly charges'}, {id:'medical',title:'Confirm the balance on a medical bill',description:'The invoice and payment receipt show different stages of the balance.',icon:'files',tone:'amber',status:'review',date:'Provider requests reply by Sep 30',category:'Bills',source:'2 source records',doc:'medical',value:'$1,240 before a recorded $400 payment'}, {id:'bonds',title:'Look for the blue folder',description:'A voice-note transcript mentions savings bonds in the hall closet.',icon:'mic',tone:'',status:'ready',date:'No date set',category:'Personal belongings',source:'1 source record',doc:'voice',value:'Value unknown'}, {id:'notify-employer',title:'Notify the former employer',description:'You recorded that the notice was sent on September 19.',icon:'mail',tone:'',status:'done',date:'Completed Sep 19',category:'Notifications',source:'Personal note',doc:'pension',value:''},{id:'gather-records',title:'Bring the first records together',description:'Eight fictional records are ready to explore in this workspace.',icon:'files',tone:'',status:'done',date:'Completed Sep 20',category:'Getting started',source:'8 sample records',doc:'policy',value:''}];
const status=t=>state.completed.includes(t.id)?'done':state.waiting.includes(t.id)?'waiting':t.status==='done'?'ready':t.status;
function go(route){if(location.hash.slice(1)===route){state.route=route;render()}else location.hash=route}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function modal(title,body,footer=''){const d=$('#detail-dialog');$('#dialog-content').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!d.open)d.showModal()}
const button=(label,action,primary=false,ico='')=>`<button class="button ${primary?'primary':''}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
function taskCard(t){return `<article class="task-card"><span class="task-symbol ${t.tone}">${icon(t.icon)}</span><div class="task-copy"><h3>${t.title}</h3><p>${t.description}</p><div class="task-meta"><span class="pill ${status(t)==='review'?'amber':status(t)==='waiting'?'blue':''}">${status(t)==='review'?'Worth a closer look':status(t)==='done'?'Completed':status(t)==='waiting'?'Waiting for a reply':'Ready when you are'}</span><span>${t.source}</span></div></div><button class="row-chevron" data-task="${t.id}" aria-label="Open ${t.title}">${icon('chevron')}</button></article>`}
function home(){const open=tasks.filter(t=>status(t)!=='done');return `<div class="page-heading"><div><div class="eyebrow">MONDAY, SEPTEMBER 21 · SAMPLE WORKSPACE</div><h1>A little clarity, Priya.</h1><p>You don’t have to do everything today. Let’s find your next step.</p></div>${button('Add documents','import',false,'plus')}</div><div class="welcome-grid"><section class="focus-card"><div class="focus-copy"><div class="eyebrow">${icon('leaf')} A PLACE TO BEGIN</div><h2>One thing at a time.</h2><p>We’ve brought the important things together, so you can move at your own pace.</p><a class="button primary" href="#plan">See your next steps ${icon('arrow')}</a></div><div class="focus-art" aria-hidden="true"></div></section><section class="summary-card"><div class="summary-title">Your progress ${icon('plan')}</div><div class="summary-value"><strong>${state.completed.length}</strong><span>of ${tasks.length} steps taken</span></div><div class="progress-track" role="progressbar" aria-label="Completed actions" aria-valuenow="${state.completed.length}" aria-valuemin="0" aria-valuemax="${tasks.length}"><span style="width:${state.completed.length/tasks.length*100}%"></span></div><div class="summary-bottom"><span><b>${open.length}</b> open actions</span><span><b>8</b> records gathered</span></div><a class="text-link" href="#plan" style="margin-top:21px">Make a little more room ${icon('arrow')}</a></section></div><div class="home-columns"><section><div class="section-title"><h2>A few things to focus on</h2><a class="text-link" href="#plan">View your plan ${icon('arrow')}</a></div>${open.slice(0,3).map(taskCard).join('')||'<div class="empty-state"><h2>A little breathing room.</h2><p>You’ve completed the sample actions.</p></div>'}<div class="memory-invitation"><p><strong>There’s a place for the personal things, too.</strong><br>Letters and little moments, whenever you feel ready.</p><a class="icon-button" href="#memories" aria-label="Visit Memories">${icon('heart')}</a></div></section><aside class="home-side"><section class="review-summary"><div class="review-icon">${icon('eye')}</div><h3>A detail worth checking.</h3><p>A policy letter and a later document name different people. Afterword has kept both records for you to review.</p><a class="text-link" href="#evidence">Look at the evidence ${icon('arrow')}</a></section><section><div class="section-title"><h2>Recently in your workspace</h2></div><div class="activity-list"><div class="activity"><span class="activity-icon">${icon('files')}</span><div><p>Eight records brought together</p><small>Sep 20 · Sample import</small></div></div><div class="activity"><span class="activity-icon">${icon('eye')}</span><div><p>Two items need a closer look</p><small>Insurance and medical records</small></div></div><div class="activity"><span class="activity-icon">${icon('check')}</span><div><p>Former employer notified</p><small>Sep 19 · Marked done by you</small></div></div></div></section></aside></div>`}
function render(){const route=nav.some(n=>n[0]===state.route)||['ask','design'].includes(state.route)?state.route:'overview';const name=nav.find(n=>n[0]===route)?.[2]||({ask:'Ask Afterword',design:'Design & research'}[route]);document.title=`${name} — Afterword`;document.documentElement.style.fontSize=state.largeText?'18px':'16px';$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview" aria-label="Afterword home"><span class="brand-mark">a</span><span>afterword</span></a><div class="estate-label"><span class="avatar">AR</span><div><small>Remembering</small><strong>Arun Rao</strong></div></div><nav aria-label="Main navigation"><div class="nav-list">${nav.slice(0,5).map(n=>navItem(n,route)).join('')}</div><div class="nav-label">A LITTLE MORE CLARITY</div><div class="nav-list">${nav.slice(5).map(n=>navItem(n,route)).join('')}</div></nav><div class="sidebar-bottom"><a class="node-label" href="#privacy">${icon('server')} Designed for HP ZGX Nano</a><div class="profile"><span class="avatar">PR</span><div><strong>Priya Rao</strong><small>Family workspace</small></div><button data-action="preferences" aria-label="Appearance preferences">${icon('settings')}</button></div></div></aside><button class="mobile-overlay" data-action="menu" aria-label="Close navigation"></button><div class="work-area"><header class="topbar"><button class="icon-button menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs"><a class="crumb-parent" href="#overview">Arun’s workspace</a><span>/</span><b>${name}</b></div><div class="top-actions"><a class="privacy-link" href="#privacy">${icon('lock')} A private place to begin</a><a class="ask-button" href="#ask">${icon('spark')} Ask Afterword</a></div></header><main id="main" class="main page-enter">${(window.views?.[route]||home)()}</main><footer class="footnote"><span class="preview-pill">${icon('info')} Interactive design preview · fictional estate · no live AI or connected accounts</span><a href="#design">Design notes & research</a></footer></div>`;afterRender()}
function navItem(n,r){return `<a class="nav-link ${n[0]===r?'active':''}" href="#${n[0]}" ${n[0]===r?'aria-current="page"':''}>${icon(n[1])}${n[2]}${n[0]==='plan'?`<span class="count">${tasks.filter(t=>status(t)!=='done').length}</span>`:''}</a>`}
function afterRender(){}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const type=a.dataset.action;if(type==='close-modal')$('#detail-dialog').close();else if(type==='menu'){const open=$('.sidebar').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',open)}else if(type==='preferences')modal('Make yourself comfortable',`<p>Choose the reading size that works for you.</p><label class="field"><span>Text size</span><select id="text-size"><option value="normal" ${!state.largeText?'selected':''}>Standard</option><option value="large" ${state.largeText?'selected':''}>Larger</option></select></label><p class="fine">Your preference stays in this browser. Reduced motion follows your device setting.</p>`,button('Save preference','save-preferences',true));else if(type==='save-preferences'){state.largeText=$('#text-size').value==='large';persist();$('#detail-dialog').close();render();toast('Reading preference saved')}else if(type==='import')window.openImport?.();else window.actions?.[type]?.(a,e)});
document.addEventListener('click',e=>{const t=e.target.closest('[data-task]');if(t)window.openTask?.(t.dataset.task)});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close()});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'overview';state.query='';render();window.scrollTo({top:0})});
window.views={overview:home};window.actions={};render();
